@startuml

class Bookmaker {}

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + date : date
}

class Runner {
  + runnerId : int
  + name : string
}

class Horse {
  + breed : string
  + age : int
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

Bookmaker "1" -- "*" Bettor
Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Runner "1" -- "1" Horse
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

